function verifyEvidence(raw: unknown, type: string, workspaceId: string, eventId: string, contentKeys: readonly string[]): Evidence<Record<string, any>> { const e = exact(raw, ["workspaceId", "eventId", "id", "fingerprint", "content"], type); if (e.workspaceId !== workspaceId || e.eventId !== eventId) fail("FOREIGN_BINDING", type); const id = identifier(e.id, `${type}.id`); const fp = fingerprint(e.fingerprint, `${type}.fingerprint`); const content = exact(e.content, contentKeys, `${type}.content`); if (content.id !== id || content.workspaceId !== workspaceId || (type !== "event" && content.eventId !== eventId) || fingerprintOf(content) !== fp) fail("CONTENT_FINGERPRINT_MISMATCH", type); return { workspaceId, eventId, id, fingerprint: fp, content } };

