    if (policy.content.participantPublicationRequirement === "REQUIRED" && (content.publicationReleaseId === null || !publication.content.current || publication.content.current.state !== "CURRENT" || publication.content.current.channelKey !== channelKey || !publication.content.current.publishedItemFingerprints.includes(content.publicationItemFingerprint))) fail("PUBLICATION_STALE", "row.publication");
