  if (selectedProgramUnits.size !== selectedProgramUnitIds.length) fail("DUPLICATE_BINDING", "sealedManifest.sources.selection.selectedProgramUnitIds");

  const requiredRoles = array(selection.requiredSpeakerRoles, "sealedManifest.sources.selection.requiredSpeakerRoles", OPERATIONS_HANDOFF_LIMITS.maxRows) as Record<string, any>[];
  const rolesById = new Map<string, Record<string, any>>();
  const rolesByUnit = new Map<string, Record<string, any>[]>();
  for (const role of requiredRoles) {
    assertRequiredSpeakerRoleFingerprint(role, "sealedManifest.sources.selection.requiredSpeakerRole");
    if (rolesById.has(role.id)) fail("DUPLICATE_BINDING", `sealedManifest.sources.selection.requiredSpeakerRoles.id:${role.id}`);
    rolesById.set(role.id, role);
    const unitRoles = rolesByUnit.get(role.programUnitId) ?? [];
    unitRoles.push(role);
    rolesByUnit.set(role.programUnitId, unitRoles);
  }

  const sourceResponseIds = array(commitments.responseIds, "sealedManifest.sources.commitments.responseIds", OPERATIONS_HANDOFF_LIMITS.maxRows).map((value) => identifier(value, "sealedManifest.sources.commitments.responseId"));
