function validateTrustedBaseline(value: unknown): { sealedEvidence: OperationsHandoffLoaderInput; sealedManifest: OperationsHandoffManifest } {
  const envelope = sealedBaselineChildren(value);
  const seen = new WeakSet<object>();
  const detachedEvidence = preflight(envelope.sealedEvidence, OPERATIONS_HANDOFF_LIMITS.maxInputBytes, "sealedEvidence", envelope.root, seen);
  const detachedManifest = preflight(envelope.sealedManifest, OPERATIONS_HANDOFF_LIMITS.maxManifestBytes, "sealedManifest", envelope.root, seen);
  const sealedEvidence = validateInputPreflighted(detachedEvidence);
  const sealedManifest = validateManifestPreflighted(detachedManifest);
  const rebuilt = build(sealedEvidence, sealedManifest.eligibility.evaluatedAt);
  if (canonicalJson(rebuilt) !== canonicalJson(sealedManifest)) fail("SEALED_BASELINE_MISMATCH", "sealedBaseline");
  return { sealedEvidence, sealedManifest };
}

/**
 * Compares current loader truth with an authenticated persisted baseline projection.
 * Authentication and persistence integrity are intentionally owned by the caller's loader/service;
 * this function only validates the exact normalized evidence-to-manifest relationship.
 */
export function classifyOperationsHandoffDrift(baseline: unknown, currentInput: unknown, deliveryEvidence: readonly { readonly path: string; readonly prior: unknown; readonly current: unknown }[] = []): OperationsHandoffDrift {
  const safeDeliveryEvidence = validateDeliveryEvidence(deliveryEvidence);
  const trusted = validateTrustedBaseline(baseline);
  const current = build(currentInput, trusted.sealedManifest.eligibility.evaluatedAt);
  const differences = diff(trusted.sealedManifest, current).filter((d) => !d.path.includes("eligibility.evaluatedAt") && !d.path.includes("eligibility.computationFingerprint"));
  const records = [{ type: "event", id: trusted.sealedManifest.event.id, fingerprint: trusted.sealedManifest.event.sourceFingerprint }, { type: "selection", id: trusted.sealedManifest.sources.selection.id, fingerprint: trusted.sealedManifest.sources.selection.fingerprint }, { type: "plan", id: trusted.sealedManifest.sources.plan.id, fingerprint: trusted.sealedManifest.sources.plan.fingerprint }, { type: "commitments", id: trusted.sealedManifest.sources.commitments.id, fingerprint: trusted.sealedManifest.sources.commitments.fingerprint }, { type: "readiness", id: trusted.sealedManifest.sources.readiness.id, fingerprint: trusted.sealedManifest.sources.readiness.fingerprint }, { type: "publication", id: trusted.sealedManifest.sources.publication.id, fingerprint: trusted.sealedManifest.sources.publication.fingerprint }, { type: "policy", id: trusted.sealedManifest.channel.policy.id, fingerprint: trusted.sealedManifest.channel.policy.fingerprint }, ...trusted.sealedManifest.files.map((file) => ({ type: "file", id: file.id as string, fingerprint: (file as Record<string, unknown>).sourceFingerprint as string }))];
  const changes = differences.map((d) => ({ ...d, family: driftFamily(d.path), materiality: !current.eligibility.eligible ? "BLOCKING" as const : d.path.includes("startsAt") || d.path.includes("endsAt") || d.path.includes("offerTermsFingerprint") ? "RECONFIRMATION" as const : d.path.startsWith("redaction.decisions") ? "INFO" as const : "OPERATOR_REVIEW" as const, sourceRecords: records }));
  const authorityInvalidated = current.sources.selection.state !== "CURRENT";
  const state = authorityInvalidated ? "AUTHORITY_INVALIDATED" : changes.length && changes.every((change) => change.materiality === "INFO") ? "NON_MATERIAL" : changes.length ? "MATERIAL" : safeDeliveryEvidence.length ? "DELIVERY_EXPORT_ONLY" : "NONE";
  return freeze({ state, sealedManifestFingerprint: fingerprintOf(trusted.sealedManifest), currentCandidateFingerprint: fingerprintOf(current), changes, deliveryDrift: safeDeliveryEvidence, eligibilityNow: current.eligibility.eligible, recommendedNextCommand: state === "NONE" || state === "NON_MATERIAL" || state === "DELIVERY_EXPORT_ONLY" ? null : "buildOperationsHandoff" });
}
